const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
const source = fs.readFileSync('.verify-script.js','utf8');
const settle = () => new Promise(resolve => setImmediate(resolve));
function setup({reduce=false, reject=false}={}) {
  const attrs = new Map();
  const events = {};
  const classes = new Set();
  let observer;
  const video = {paused:true, dataset:{src:'assets/scene.webm'}, plays:0,
    hasAttribute:k=>attrs.has(k),
    set src(v){attrs.set('src',v)}, get src(){return attrs.get('src')},
    pause(){this.paused=true},
    play(){this.plays++; if(reject)return Promise.reject(new Error('blocked')); this.paused=false;return Promise.resolve()},
    addEventListener:(k,f)=>events['video:'+k]=f};
  const control = {hidden:true, classList:{toggle:(k,on)=>on?classes.add(k):classes.delete(k)},
    setAttribute:(k,v)=>attrs.set(k,v), addEventListener:(k,f)=>events['control:'+k]=f};
  const film = {querySelector:k=>k==='video'?video:control,
    classList:{add:k=>classes.add(k),remove:k=>classes.delete(k)}};
  const reduced = {matches:reduce,addEventListener:(k,f)=>events.reduce=f};
  const document = {hidden:false,querySelector:()=>film,addEventListener:(k,f)=>events[k]=f};
  class IntersectionObserver {constructor(callback){observer=callback}observe(){}}
  vm.runInNewContext(source,{document,matchMedia:()=>reduced,window:{IntersectionObserver},IntersectionObserver});
  return {video,control,classes,attrs,events,reduced,document,intersection:visible=>observer([{isIntersecting:visible}]),allow:()=>{reject=false}};
}
(async()=>{
  let s=setup();await settle();
  assert.equal(s.video.src,'assets/scene.webm');assert.equal(s.video.paused,false);assert.equal(s.control.hidden,false);assert(s.classes.has('has-frame'));
  s.events['control:click']();await settle();assert(s.video.paused);assert.equal(s.attrs.get('aria-label'),'Play background film');
  s.intersection(false);s.intersection(true);await settle();assert(s.video.paused,'user pause persists across viewport changes');
  s.events['control:click']();await settle();assert("'!s.video.paused);
  s.document.hidden=true;s.events.visibilitychange();await settle();assert(s.video.paused);
  s.document.hidden=false;s.events.visibilitychange();await settle();assert(!s.video.paused);
  s.reduced.matches=true;s.events.reduce();await settle();assert(s.video.paused);assert(s.control.hidden);assert(!s.classes.has('"'has-frame'));
  s=setup({reduce:true});await settle();assert.equal(s.video.src,undefined);assert(s.video.paused);assert(s.control.hidden);
  s=setup({reject:true});await settle();assert("'!s.classes.has('"'has-frame'));assert.equal(s.attrs.get('aria-label'),'Play background film');assert("'!s.control.hidden);
  s.allow();s.events['"'control:click']();await settle();assert("'!s.video.paused);assert(s.classes.has('"'has-frame'));
  s.events['video:error']();await settle();assert(s.video.paused);assert(s.control.hidden);assert("'!s.classes.has('"'has-frame'));
  console.log('PASS: playback, pause/restart, persistent user pause, visibility suspension, reduced-motion initial and live change, autoplay rejection/retry, media error fallback. Tests use a simulated DOM, not a rendered browser.');
})().catch(e=>{console.error(e);process.exitCode=1});
